import{_ as s,o as i,c as t,ax as a}from"./chunks/framework.D0-oyZN4.js";const u=JSON.parse('{"title":"Get Started with the CLI","description":"Install the Developer Studio CLI, pair a session with your community, scaffold your first widget, and preview it live.","frontmatter":{"description":"Install the Developer Studio CLI, pair a session with your community, scaffold your first widget, and preview it live."},"headers":[],"relativePath":"cli/getting-started.md","filePath":"cli/getting-started.md"}'),o={name:"cli/getting-started.md"};function n(r,e,d,l,h,c){return i(),t("div",null,[...e[0]||(e[0]=[a(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/getting-started.md for this page in Markdown format</div><h1 id="get-started-with-the-cli" tabindex="-1">Get Started with the CLI <a class="header-anchor" href="#get-started-with-the-cli" aria-label="Permalink to &quot;Get Started with the CLI&quot;">​</a></h1><p>In this tutorial, you will install the <strong>Developer Studio CLI</strong>, pair it with your community, scaffold a React widget, and preview it inside your community&#39;s No-Code Builder. By the end, you will have a working local development loop and know how to iterate on a widget without publishing anything.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You need:</p><ul><li>Node.js 18 or later</li><li>A community account with developer access</li><li>Access to <strong>CLI Access</strong> under <strong>Integrations → Developer Studio</strong> in your community, so you can get a pairing code</li></ul><h2 id="_1-install-the-cli" tabindex="-1">1. Install the CLI <a class="header-anchor" href="#_1-install-the-cli" aria-label="Permalink to &quot;1. Install the CLI&quot;">​</a></h2><p>Install <code>gsds</code> globally with npm:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @gainsight-hub/developer-studio-cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>You should see a version like <code>1.8.2</code> or newer.</p><h2 id="_2-set-up-your-project-directory" tabindex="-1">2. Set up your project directory <a class="header-anchor" href="#_2-set-up-your-project-directory" aria-label="Permalink to &quot;2. Set up your project directory&quot;">​</a></h2><p><code>gsds init</code> handles two situations. Use whichever matches you.</p><p><strong>Starting from scratch</strong>, with an empty or nonexistent directory:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-widgets</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-widgets</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Reusing an existing repo</strong> — for example one cloned from the <a href="https://github.com/gainsight-hub/widgets-repository-template" target="_blank" rel="noreferrer">Widgets Repository Template</a>, or any project that already has <code>extensions_registry.json</code>, <code>connectors_registry.json</code>, or a <code>gsds.json</code>:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-widgets</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>gsds init</code> recognizes that shape automatically — no extra flag needed — and backfills only whatever&#39;s missing (<code>gsds.json</code>, <code>AGENTS.md</code>, <code>README.md</code>, <code>.gitignore</code>, and the registries if absent). It never overwrites a file it finds, so nothing you already have is at risk.</p><p>Only reach for <code>--force</code> when the directory is non-empty <strong>and</strong> doesn&#39;t already look like a widget project — for instance a brand-new GitHub repo created with just a <code>README.md</code> or <code>LICENSE</code>. <code>--force</code> means &quot;this directory is safe to scaffold into, trust me&quot;; it does not loosen the never-overwrite guarantee, and it isn&#39;t the default answer for &quot;I already have a repo&quot; — most existing widget repos are recognized without it. See <a href="./reference/commands.html#gsds-init"><code>gsds init</code></a> in the command reference for the exact list of what&#39;s recognized.</p><h2 id="_3-pair-a-session-with-your-community" tabindex="-1">3. Pair a session with your community <a class="header-anchor" href="#_3-pair-a-session-with-your-community" aria-label="Permalink to &quot;3. Pair a session with your community&quot;">​</a></h2><p>In your community admin, open <strong>Integrations → Developer Studio → CLI Access</strong> and copy the pairing code shown there. Then redeem it in your terminal:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PAIRING-CODE-FROM-COMMUNITY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pairing codes are single-use and expire <strong>1 minute</strong> after they are issued, so open <strong>CLI Access</strong> with your terminal already open. The resulting session token is stored in your OS keychain, is tenant-scoped, and lasts <strong>8 hours</strong>.</p><p>Use the same account you sign in to your community with. Preview sessions are matched per user, so a session paired under one account is not visible to another in the No-Code Builder.</p><p>You can confirm the session at any time:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_4-scaffold-a-widget" tabindex="-1">4. Scaffold a widget <a class="header-anchor" href="#_4-scaffold-a-widget" aria-label="Permalink to &quot;4. Scaffold a widget&quot;">​</a></h2><p>From your project root, scaffold a React widget:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-overview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --framework</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --category</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Analytics</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>gsds create</code> writes a new folder under <code>widgets/revenue-overview/</code> with a <code>package.json</code> that includes a <code>dev</code> script (required for previewing) and starter source files, and appends the widget&#39;s entry to <code>extensions_registry.json</code>.</p><p>There is no per-widget <code>widget.json</code>. <code>extensions_registry.json</code> is where a widget is declared — a folder the registry doesn&#39;t mention is invisible to your community, and <code>gsds build</code> warns when it finds one.</p><h2 id="_5-preview-it-in-your-community" tabindex="-1">5. Preview it in your community <a class="header-anchor" href="#_5-preview-it-in-your-community" aria-label="Permalink to &quot;5. Preview it in your community&quot;">​</a></h2><p>Start the local dev server:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>gsds preview</code> requires an active session (you just paired one). It boots each widget&#39;s <code>dev</code> script and registers a preview session with your community.</p><h3 id="allow-the-browser-to-reach-your-local-server" tabindex="-1">Allow the browser to reach your local server <a class="header-anchor" href="#allow-the-browser-to-reach-your-local-server" aria-label="Permalink to &quot;Allow the browser to reach your local server&quot;">​</a></h3><p>Do this before you open the picker. <code>gsds preview</code> serves from <code>http://localhost:5173</code> by default, and each widget with its own <code>dev</code> script serves from a further port. Your community page — served over HTTPS — loads from those addresses directly, and Chrome 142 and later ask permission the first time, with a prompt about looking for and connecting to devices on your local network. Other Chromium-based browsers behave the same way.</p><p>Choose <strong>Allow</strong>. Until it is allowed, the browser cannot reach your local server and your local widgets do not load. If you blocked it by mistake, reopen the choice from the site settings icon at the left of the address bar and reload the page.</p><h3 id="open-the-picker" tabindex="-1">Open the picker <a class="header-anchor" href="#open-the-picker" aria-label="Permalink to &quot;Open the picker&quot;">​</a></h3><p>Open your community, browse to a page, and open the widget picker in the No-Code Builder. Your local widgets appear alongside published ones while <code>gsds preview</code> is running. Edit files under <code>widgets/revenue-overview/</code> and the picker reflects your changes.</p><p>If a widget does not appear, work through <a href="./reference/troubleshooting.html#widget-missing-from-the-picker">Widget missing from the picker</a>.</p><p>Stop the preview with <code>Ctrl-C</code>.</p><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><ul><li>How to install <code>gsds</code> and confirm it works</li><li>How to pair a session with a pairing code, under the account you browse the community with</li><li>How to scaffold a project and a widget</li><li>How to preview local widgets against your community</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Learn the full session model — pairing, expiry, and logout — in <a href="./authenticate.html">Authenticate</a></li><li>Add a Connector and run it against your tenant with <a href="./test-connectors.html">Test Connectors</a></li><li>See every command and flag in the <a href="./reference/commands.html">Command reference</a></li><li>Match an error message or a silent failure to its cause in <a href="./reference/troubleshooting.html">Troubleshooting</a></li></ul>`,45)])])}const g=s(o,[["render",n]]);export{u as __pageData,g as default};
